from collections import deque

def bf(planet1, planet2):
    # Check if both planet names are valid
    if planet1 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()

    if planet2 not in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]:
        return ()

    # Initialize a deque with the planets' orbits
    dq = deque(sorted([planet for planet in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus"]]))

    # Add the first planet's orbit to the deque
    dq.appendleft(planet1)

    # Iterate through the remaining planets
    while dq:
        current_planet = dq.popleft()

        # If the current planet's orbit is between the orbits of the two given planets,
        # add it to the result list
        if planet2 in dq:
            dq.append(current_planet)

    # Return the resulting list of planets
    return tuple(dq)

